def compute(vars):
    total_personnel = vars["v2"]
    passenger_service_personnel = vars["v1"]

    if total_personnel == 0:
        return None

    percentage = passenger_service_personnel / total_personnel * 100

    return {
        "value": percentage,
        "trace": {
            "passenger_service_personnel": passenger_service_personnel,
            "total_personnel": total_personnel,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
